(function(){'use strict';
const dict=window.G123_ZHUYIN||{};
const phrases={'重現':'ㄔㄨㄥˊ ㄒㄧㄢˋ','為暫定':'ㄨㄟˊ ㄗㄢˋ ㄉㄧㄥˋ','一次':'ㄧˊ ㄘˋ','數學':'ㄕㄨˋ ㄒㄩㄝˊ','數量':'ㄕㄨˋ ㄌㄧㄤˋ','數字':'ㄕㄨˋ ㄗˋ','數線':'ㄕㄨˋ ㄒㄧㄢˋ','數一數':'ㄕㄨˇ ㄧ ㄕㄨˇ','點數':'ㄉㄧㄢˇ ㄕㄨˇ','長度':'ㄔㄤˊ ㄉㄨˋ','長方形':'ㄔㄤˊ ㄈㄤ ㄒㄧㄥˊ','長短':'ㄔㄤˊ ㄉㄨㄢˇ','家長':'ㄐㄧㄚ ㄓㄤˇ','空格':'ㄎㄨㄥˋ ㄍㄜˊ','空白':'ㄎㄨㄥˋ ㄅㄞˊ','空位':'ㄎㄨㄥˋ ㄨㄟˋ','相同':'ㄒㄧㄤ ㄊㄨㄥˊ','合起來':'ㄏㄜˊ ㄑㄧˇ ㄌㄞˊ','和是':'ㄏㄜˊ ㄕˋ','總和':'ㄗㄨㄥˇ ㄏㄜˊ','重量':'ㄓㄨㄥˋ ㄌㄧㄤˋ','重新':'ㄔㄨㄥˊ ㄒㄧㄣ','重做':'ㄔㄨㄥˊ ㄗㄨㄛˋ','行列':'ㄏㄤˊ ㄌㄧㄝˋ','一行':'ㄧˋ ㄏㄤˊ','分數':'ㄈㄣ ㄕㄨˋ','分成':'ㄈㄣ ㄔㄥˊ','幾分':'ㄐㄧˇ ㄈㄣ','部分':'ㄅㄨˋ ㄈㄣˋ','一個':'ㄧˊ ㄍㄜˋ','一樣':'ㄧˊ ㄧㄤˋ','一張':'ㄧˋ ㄓㄤ','一位':'ㄧˊ ㄨㄟˋ','一條':'ㄧˋ ㄊㄧㄠˊ','一題':'ㄧˋ ㄊㄧˊ','一份':'ㄧˊ ㄈㄣˋ','不是':'ㄅㄨˊ ㄕˋ','不會':'ㄅㄨˊ ㄏㄨㄟˋ'};
const keys=Object.keys(phrases).sort((a,b)=>b.length-a.length);
function annotate(text){const frag=document.createDocumentFragment();for(let i=0;i<text.length;){let key=keys.find(k=>text.startsWith(k,i));let word=key||text[i], sounds=key?phrases[key].split(' '):[dict[word]];[...word].forEach((ch,j)=>{if(sounds[j]){const el=document.createElement('span');el.className='zy-char';el.dataset.sound=sounds[j];el.textContent=ch;frag.appendChild(el)}else frag.appendChild(document.createTextNode(ch))});i+=word.length}return frag}
function process(root){if(root.nodeType===3){const parent=root.parentElement;if(!parent||parent.closest('script,style,textarea,option,select,svg,math,.zy-char,.zy-mirror,[contenteditable]')||!/[\u3400-\u9fff]/.test(root.nodeValue))return;root.replaceWith(annotate(root.nodeValue));return}if(root.nodeType!==1&&root.nodeType!==9)return;if(root.nodeType===1&&root.closest('script,style,textarea,option,select,svg,math,.zy-char,.zy-mirror,[contenteditable]'))return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let list=[],n;while(n=walker.nextNode())list.push(n);list.forEach(process)}
function mirror(select){let el=select.nextElementSibling;if(!el||!el.classList.contains('zy-mirror')){el=document.createElement('div');el.className='zy-mirror';el.setAttribute('aria-hidden','true');select.insertAdjacentElement('afterend',el)}el.replaceChildren(annotate(select.selectedOptions[0]?.textContent||''))}
function start(){process(document.body);document.querySelectorAll('select').forEach(s=>{mirror(s);s.addEventListener('change',()=>mirror(s))});const obs=new MutationObserver(records=>{for(const r of records){if(r.type==='characterData')process(r.target);else r.addedNodes.forEach(process)}});obs.observe(document.body,{childList:true,subtree:true,characterData:true})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
})();
